sys_script_include.script:
var CiscoSecureAccessCreatePrivateResource = Class.create();
CiscoSecureAccessCreatePrivateResource.prototype = {
	initialize: function () {
	},

	createPrivateResource: function (input) {
		var result = {
			status: "error",
			message: "",
			request: {},
			payload: {},
			response: {}
		};

		try {
			// --- Step 1: Input Mapping ---
			var name = input.privateResourceName || "";
			var desc = input.description || "";
			var ipAddr = input.internallyAddress || "";
			var proto = input.protocol || "ANY-TCP";
			var ports = input.portRanges || "";
			var rgType = (input.resourceGroupType || "").toLowerCase(); // allow or block
			var reachableAddr = input.remotelyReachableAccess || input.internallyAddress || "";


			// Mandatory fields checks //
			var missingFields = [];
			if (!name) missingFields.push("privateResourceName");
			if (!ipAddr) missingFields.push("internallyAddress");
			if (!rgType) missingFields.push("resourceGroupType");
			if (!proto) missingFields.push("protocol");

			if (missingFields.length > 0) {
				gs.error("[Cisco Secure Access -SI] ERROR: Missing mandatory fields: " + missingFields.join(", "));
				result.message = "Missing mandatory fields: " + missingFields.join(", ");
				return result;
			}

			// --- Step 2: Fetch all Allow and Block Resource Groups --- //
			var allowGroups = [];
			var blockGroups = [];

			var listGR = new GlideRecord('u_cisco_secure_access_private_resources_group');
			listGR.addQuery('u_active_status', 'Active');
			listGR.query();
			while (listGR.next()) {
				var groupType = (listGR.u_resource_group_for + "").toLowerCase();
				var groupObj = {
					id: listGR.u_resource_group_id + "",
					name: listGR.u_name + ""
				};

				if (groupType.indexOf('allow') !== -1) {
					allowGroups.push(groupObj);
				} else if (groupType.indexOf('block') !== -1) {
					blockGroups.push(groupObj);
				}
			}

			gs.info("[Cisco Secure Access -SI] Allow Groups: " + JSON.stringify(allowGroups));
			gs.info("[Cisco Secure Access -SI] Block Groups: " + JSON.stringify(blockGroups));


			// --- Step 3: Build Access Types (Correct Cisco Secure Access  format) ---
			var accessTypes = [];

			// DO NOT ADD branch type here!
			// if (input.branchConnections) {
			//     accessTypes.push({ type: "branch" });
			// }

			if (input.zeroTrustConnections) {
				// Generate a unique FQDN prefix, e.g., use app name or timestamp
				var fqdnPrefix = (input.externalFQDNPrefix || (name.replace(/\s+/g, '-').toLowerCase().substring(0, 10) + '-' + new Date().getTime()));
				var browserProtocol = "HTTPS";
				accessTypes.push({
					type: "browser",
					externalFQDNPrefix: fqdnPrefix,
					protocol: browserProtocol,
					sni: input.sni || "",
					sslVerificationEnabled: input.sslVerificationEnabled !== false,
					isWebsocketEnabled: input.isWebsocketEnabled !== undefined ? input.isWebsocketEnabled : false
				});
			}

			if (input.vpnConnections) {
				accessTypes.push({ type: "network" });
			}

			if (input.clientBaseConnection) {
				var reachableArr = [];
				if (reachableAddr) reachableArr.push(reachableAddr);
				accessTypes.push({
					type: "client",
					reachableAddresses: reachableArr
				});
			}

			if (accessTypes.some(function(a){return a.type==="browser";})) {
				var allowedBrowserProtocols = ["HTTP/HTTPS", "SSH", "RDP-TCP"];
				// Auto-map TCP to HTTP/HTTPS for browser-based access if address is IPv4/IPv6
				if (proto === "TCP") {
					if (isIPv4(ipAddr) || isIPv6(ipAddr)) {
						proto = "HTTP/HTTPS";
					} else if (isFQDN(ipAddr) || isWildcardFQDN(ipAddr)) {
						proto = "RDP-TCP"; // or "SSH" if that's your preferred default
					}
				}
				if (allowedBrowserProtocols.indexOf(proto) === -1) {
					gs.error("[Cisco Secure Access -SI] ERROR: For browser-based access, protocol must be one of: " + allowedBrowserProtocols.join(", "));
					result.status = "error";
					result.message = "For browser-based access, protocol must be one of: " + allowedBrowserProtocols.join(", ");
					return result;
				}
			}


			// --- Step 4: Resource Addresses  ---
			var mappedProtocol = proto;

			var resourceAddresses = [{
				destinationAddr: [ipAddr],
				protocolPorts: [{
					protocol: mappedProtocol,
					ports: ports
				}]
			}];

			// --- Step 5: Resource Groups mapping ---
			var resourceGroupIds = [];

			if (rgType === "allow") {
				for (var i = 0; i < allowGroups.length; i++) {
					resourceGroupIds.push(parseInt(allowGroups[i].id, 10));
				}
			} else if (rgType === "block") {
				for (var i = 0; i < blockGroups.length; i++) {
					resourceGroupIds.push(parseInt(blockGroups[i].id, 10));
				}
			}

			if (resourceGroupIds.length === 0) {
				gs.error("[Cisco Secure Access -SI] ERROR: No resource group ID found for type " + rgType);
				result.message = "No resource group ID found for type " + rgType;
				return result;
			}

			gs.info("[Cisco Secure Access -SI] Selected Resource Group Type: " + rgType + ", Final IDs: " + resourceGroupIds.join(","));


			// --- Step 6: Build Cisco Secure Access  payload with only non-empty fields ---
			var payload = {};

			// Required fields
			if (name) payload.name = name;
			if (desc) payload.description = desc;
			if (accessTypes && accessTypes.length > 0) payload.accessTypes = accessTypes;
			if (resourceAddresses && resourceAddresses.length > 0) payload.resourceAddresses = resourceAddresses;
			if (resourceGroupIds && resourceGroupIds.length > 0) payload.resourceGroupIds = resourceGroupIds;

			// Optional: include only if explicitly set
			if (input.changeRemotelyAddress === true) payload.changeRemotelyAddress = true;


			// --- Step 7: Insert into CMDB ---
			var appGR = new GlideRecord('u_cmdb_ci_application');
			appGR.addQuery('name', name);
			appGR.query();

			var appSysId = null;
			if (appGR.next()) {
				// Record exists, skip insert and save sys_id for update later
				appSysId = appGR.sys_id + "";
				gs.info("[Cisco Secure Access -SI] CMDB entry already exists for " + name + ", sys_id: " + appSysId);
			} else {
				// Insert new record as before
				appGR.initialize();
				appGR.name = name;
				appGR.short_description = desc;
				appGR.ip_address = ipAddr;
				appGR.resource_addresses = JSON.stringify(resourceAddresses);
				appGR.access_types = JSON.stringify(accessTypes);
				appGR.resource_group = rgType;
				appGR.resource_group_ids = resourceGroupIds.join(",");
				appGR.status = "Created";
				appGR.u_public_or_private = "private";
				appSysId = appGR.insert();
				gs.info("[Cisco Secure Access -SI] CMDB entry created for {0} with RG {1}", name, rgType);
			}

			// --- Step 8: Call Cisco Secure Access  REST API (Insert) ---
			try {
				var restMsg = new sn_ws.RESTMessageV2('Cisco Secure Access Private Resources', 'Create Private Resources');
				restMsg.setHttpMethod('POST');
				restMsg.setRequestHeader("Content-Type", "application/json");
				restMsg.setRequestHeader("Accept", "application/json");

				// Token fetcher
				try {
					var token = new CiscoSecureAccessGetToken().getLatestAccessToken();
					gs.info('[Cisco Secure Access -SI] Token fetched: ' + token);

					restMsg.setRequestHeader("Authorization", "Bearer " + token);
				} catch (ex) {
					gs.error('[Cisco Secure AccessSI] Failed to fetch token: ' + ex.message);
					result.status = "error";
					result.message = "Token fetch failed: " + ex.message;
					return result;
				}

				// Log the final payload before sending
				gs.info("[Cisco Secure Access -SI] FINAL PAYLOAD TO Cisco Secure Access API: " + JSON.stringify(payload));

				restMsg.setRequestBody(JSON.stringify(payload));

				var response = restMsg.execute();
				var statusCode = response.getStatusCode();
				var body = response.getBody();

				gs.info("[Cisco Secure Access -SI] Cisco Secure Access  REST Response: Status={0} | Body={1}", statusCode, body);

				// Store actual Cisco Secure Access  response
				result.response.statusCode = statusCode;
				result.response.rawResponse = body;

				// Try to parse JSON
				var parsed;
				try {
					parsed = JSON.parse(body);
				} catch (e) {
					parsed = { error: "Non-JSON response", body: body };
				}
				result.response.parsed = parsed;

				// Use real status + Cisco Secure Access  error if available
				if (statusCode == 200 || statusCode == 201) {
					result.status = "success";
					result.message = "Cisco Secure Access  Private Resource created successfully";
					result.response.id = parsed.resourceId ||"";
					result.response.name = parsed.name || name;

					// --- Update CMDB record with resource ID from API ---
					if ((parsed.resourceId || parsed.id) && appSysId) {
						var updateGR = new GlideRecord('u_cmdb_ci_application');
						if (updateGR.get(appSysId)) {
							updateGR.u_resource_id = parsed.resourceId || parsed.id;
							updateGR.update();
						}
					}
				} else {
					result.status = "error";
					result.message = parsed.error || ("Cisco Secure Access  API failed with status " + statusCode);
				}
			} catch (restEx) {
				gs.error("[Cisco Secure Access -SI] REST call exception: " + restEx.message);
				result.message = restEx.message;
			}

			result.request = input;
			result.payload = payload;

		} catch (ex) {
			gs.error("[Cisco Secure Access -SI] Error: " + ex.message);
			result.message = ex.message;
		}

		return result;
	},

	type: 'CiscoSecureAccessCreatePrivateResource'
};

function isIPv4(addr) {
    return /^(\d{1,3}\.){3}\d{1,3}$/.test(addr);
}
function isIPv6(addr) {
    return /^([a-fA-F0-9:]+:+)+[a-fA-F0-9]+$/.test(addr);
}
function isFQDN(addr) {
    return /^[a-zA-Z0-9-]+(\.[a-zA-Z0-9-]+)+$/.test(addr);
}
function isWildcardFQDN(addr) {
    return /^\*\.[a-zA-Z0-9-]+(\.[a-zA-Z0-9-]+)+$/.test(addr);
}
